            "x_t": "The feature vector at time t within the sliding window."
        }
    },
    "RollingLinearRegressionResiduals": {
        "description": "[Machine Learning based Factor] This factor captures the deviation from local linear trends by performing a rolling linear regression on price returns over a short window. The residuals from this regression represent the mean-reversion signal, isolating noise from trend-following components. Positive residuals indicate prices are above the local trend (potential mean-reversion down), and negative residuals indicate prices are below the local trend (potential mean-reversion up).",
        "formulation": "$$ RLRR_t = y_t - \\hat{y}_t = y_t - (\\beta_0 + \\beta_1 \\cdot t) $$\nWhere $y_t$ is the log-return at time $t$, $\\hat{y}_t$ is the predicted value from the rolling linear regression over window $W$, and $\\beta_0, \\beta_1$ are the intercept and slope coefficients estimated over the window.",
        "variables": {
            "window_size": "The look-back period for the rolling linear regression, set to 30 minutes (30 bars).",
            "y_t": "The log-return at time t, calculated as $\\ln(P_t / P_{t-1})$.",
            "t": "The time index within the rolling window, normalized to [0, 1].",
            "beta_0": "The intercept coefficient of the rolling linear regression.",
            "beta_1": "The slope coefficient of the rolling linear regression."
        }
    }
}

